import cpp

pragma[noinline]
predicate possiblyIncompleteFile(File f) {
  exists(Diagnostic d | d.getFile() = f and d.getSeverity() >= 3)
}

predicate immediatelyReachableFunction(Function f) {
  not f.isStatic()
  or
  exists(BlockExpr be | be.getFunction() = f)
  or
  f instanceof MemberFunction
  or
  f instanceof TemplateFunction
  or
  f.getFile() instanceof HeaderFile
  or
  f.getAnAttribute().hasName("constructor")
  or
  f.getAnAttribute().hasName("destructor")
  or
  f.getAnAttribute().hasName("used")
  or
  f.getAnAttribute().hasName("unused")
  or

  possiblyIncompleteFile(f.getFile())
}

predicate immediatelyReachableVariable(Variable v) {
  v.isTopLevel() and not v.isStatic()
  or
  exists(v.getDeclaringType())
  or
  v.getFile() instanceof HeaderFile
  or
  v.getAnAttribute().hasName("used")
  or
  v.getAnAttribute().hasName("unused")
}

class ImmediatelyReachableThing extends Thing {
  ImmediatelyReachableThing() {
    immediatelyReachableFunction(this) or
    immediatelyReachableVariable(this)
  }
}

predicate reachableThing(Thing t) {
  t instanceof ImmediatelyReachableThing
  or
  exists(Thing mid | reachableThing(mid) and mid.callsOrAccesses() = t)
}

pragma[nomagic]
predicate callsOrAccessesPlus(Thing thing1, FunctionToRemove thing2) {
  thing1.callsOrAccesses() = thing2
  or
  exists(Thing mid |
    thing1.callsOrAccesses() = mid and
    callsOrAccessesPlus(mid, thing2)
  )
}

class Thing extends Locatable {
  Thing() {
    this instanceof Function or
    this instanceof Variable
  }

  string getName() {
    result = this.(Function).getName() or
    result = this.(Variable).getName()
  }

  Thing callsOrAccesses() {
    this.(Function).calls(result)
    or
    this.(Function).accesses(result.(Function))
    or
    this.(Function).accesses(result.(Variable))
    or
    exists(Access a | this.(Variable).getInitializer().getExpr().getAChild*() = a |
      result = a.getTarget()
    )
  }
}

class FunctionToRemove extends Function {
  FunctionToRemove() {
    this.hasDefinition() and
    not reachableThing(this)
  }

  Thing getOther() {
    callsOrAccessesPlus(result, this) and
    this != result and


    not result instanceof LocalVariable
  }
}

from FunctionToRemove f, string clarification, Thing other
where
  if exists(f.getOther())
  then (
    clarification = " ($@ must be removed at the same time)" and
    other = f.getOther()
  ) else (
    clarification = "" and other = f
  )
select f, "Static function " + f.getName() + " is unreachable" + clarification, other,
  other.getName()

import cpp
import semmle.code.cpp.ir.IR
import semmle.code.cpp.ir.ValueNumbering
import PathGraph


class NullInstruction extends ConstantValueInstruction {
  NullInstruction() {
    this.getValue() = "0" and
    this.getResultIRType() instanceof IRAddressType
  }
}


predicate explicitNullTestOfInstruction(Instruction checked, Instruction bool) {
  bool =
    any(CompareInstruction cmp |
      exists(NullInstruction null |
        cmp.getLeft() = null and cmp.getRight() = checked
        or
        cmp.getLeft() = checked and cmp.getRight() = null
      |
        cmp instanceof CompareEQInstruction
        or
        cmp instanceof CompareNEInstruction
      )
    )
  or
  bool =
    any(ConvertInstruction convert |
      checked = convert.getUnary() and
      convert.getResultIRType() instanceof IRBooleanType and
      checked.getResultIRType() instanceof IRAddressType
    )
}

pragma[nomagic]
predicate candidateResult(LoadInstruction checked, ValueNumber value, IRBlock dominator) {
  explicitNullTestOfInstruction(checked, _) and
  not checked.getAst().isInMacroExpansion() and
  value.getAnInstruction() = checked and
  dominator.dominates(checked.getBlock())
}


module PathGraph {

  private predicate isSource(Instruction address, LoadInstruction deref) {
    exists(ValueNumber sourceValue |
      candidateResult(_, sourceValue, deref.getBlock()) and
      sourceValue.getAnInstruction() = address and
      deref.getSourceAddress() = address
    )
  }


  private predicate isSink(LoadInstruction checked, ValueNumber vn) {
    candidateResult(checked, vn, _)
  }


  private predicate fwdFlow(Instruction i) {
    isSource(i, _)
    or
    exists(Instruction mid |
      fwdFlow(mid) and
      mid.getASuccessor() = i
    )
  }


  private predicate revFlow(Instruction i, ValueNumber vn) {
    fwdFlow(i) and
    (
      isSink(i, vn)
      or
      exists(Instruction mid |
        revFlow(mid, vn) and
        i.getASuccessor() = mid
      )
    )
  }


  private Instruction getASuccessor(Instruction i) {
    exists(ValueNumber vn |
      vn.getAnInstruction() = i and
      result = getASuccessorWithValueNumber(i, vn)
    )
  }


  private Instruction getASuccessorWithValueNumber(Instruction i, ValueNumber vn) {
    revFlow(i, vn) and
    result = getASuccessorWithValueNumber0(vn, i.getASuccessor()) and
    vn.getAnInstruction() = i
  }

  pragma[nomagic]
  private Instruction getASuccessorWithValueNumber0(ValueNumber vn, Instruction i) {
    result = getASuccessorIfDifferentValueNumberTC(vn, i) and
    vn.getAnInstruction() = result
  }


  private Instruction getASuccessorIfDifferentValueNumberTC(ValueNumber vn, Instruction i) {
    revFlow(i, vn) and
    (
      i = result and
      vn.getAnInstruction() = i
      or
      exists(Instruction mid |
        mid = getASuccessorIfDifferentValueNumber(vn, i) and
        result = getASuccessorIfDifferentValueNumberTC(vn, mid)
      )
    )
  }


  private Instruction getASuccessorIfDifferentValueNumber(ValueNumber vn, Instruction i) {
    revFlow(i, vn) and
    revFlow(result, vn) and
    not vn.getAnInstruction() = i and
    pragma[only_bind_into](result) = pragma[only_bind_into](i).getASuccessor()
  }

  query predicate nodes(Instruction i, string key, string val) {
    revFlow(i, _) and
    key = "semmle.label" and
    val = i.getAst().toString()
  }


  query predicate edges(Instruction i1, Instruction i2) {
    getASuccessor(i1) = i2
    or



    exists(Instruction mid |
      isSource(mid, i1) and
      getASuccessor(mid) = i2
    )
  }
}

from LoadInstruction checked, LoadInstruction deref, ValueNumber sourceValue, IRBlock dominator
where
  candidateResult(checked, sourceValue, dominator) and
  sourceValue.getAnInstruction() = deref.getSourceAddress() and





  deref.getBlock() = dominator
select checked, deref, checked, "This null check is redundant because $@ in any case.", deref,
  "the value is dereferenced"

import cpp

predicate exclude(Function f) {
  exists(string name | name = f.getName() |
    name.toLowerCase().matches("get%") or
    name.matches("strto%")
  )
}

predicate checkExpr(Expr e, string operation, Variable v) {
  exists(FunctionCall fc | fc = e and not exclude(fc.getTarget()) |
    fc.getTarget().getName() = operation and
    (fc.getAnArgument() = v.getAnAccess() or fc.getQualifier() = v.getAnAccess())
  )
  or
  exists(DeleteExpr del | del = e |
    del.getExpr() = v.getAnAccess() and
    operation = "delete"
  )
  or
  exists(DeleteArrayExpr del | del = e |
    del.getExpr() = v.getAnAccess() and
    operation = "delete[]"
  )
}

predicate checkedFunctionCall(FunctionCall fc, string operation) {
  relevantFunctionCall(fc, _) and
  exists(Variable v, Expr check | v.getAnAssignedValue() = fc |
    checkExpr(check, operation, v) and
    check != fc
  )
}

predicate relevantFunctionCall(FunctionCall fc, Function f) {
  fc.getTarget() = f and
  exists(Variable v | v.getAnAssignedValue() = fc) and
  not okToIgnore(fc)
}

predicate okToIgnore(FunctionCall fc) { fc.isInMacroExpansion() }

predicate functionStats(Function f, string operation, int used, int total, int percentage) {
  exists(PointerType pt | pt.getATypeNameUse() = f.getADeclarationEntry()) and
  used = strictcount(FunctionCall fc | checkedFunctionCall(fc, operation) and f = fc.getTarget()) and
  total = strictcount(FunctionCall fc | relevantFunctionCall(fc, f)) and
  percentage = used * 100 / total
}

from FunctionCall unchecked, Function f, string operation, int percent
where
  relevantFunctionCall(unchecked, f) and
  not checkedFunctionCall(unchecked, operation) and
  functionStats(f, operation, _, _, percent) and
  percent >= 70 and
  unchecked.getFile().getAbsolutePath().matches("%fbcode%") and
  not unchecked.getFile().getAbsolutePath().matches("%\\_build%")
select unchecked,
  "After " + percent.toString() + "% of calls to " + f.getName() + " there is a call to " +
    operation + " on the return value. The call may be missing in this case."

import cpp
import semmle.code.cpp.ir.dataflow.DataFlow
import CastToPointerArithFlow::PathGraph

Type getFullyConvertedType(DataFlow::Node node) {
  result = node.asExpr().getFullyConverted().getUnspecifiedType()
}

module CastToPointerArithFlowConfig implements DataFlow::StateConfigSig {
  class FlowState = Type;

  predicate isSource(DataFlow::Node node, FlowState state) {
    not node.asExpr() instanceof Conversion and
    exists(Type baseType1, Type baseType2 |
      hasBaseType(node.asExpr(), baseType1) and
      hasBaseType(node.asExpr().getConversion*(), baseType2) and
      introducesNewField(baseType1, baseType2)
    ) and
    getFullyConvertedType(node) = state
  }

  predicate isSink(DataFlow::Node node, FlowState state) {
    (
      exists(PointerAddExpr pae | pae.getAnOperand() = node.asExpr()) or
      exists(ArrayExpr ae | ae.getArrayBase() = node.asExpr())
    ) and
    getFullyConvertedType(node) = state
  }

  predicate isBarrierIn(DataFlow::Node node) { isSource(node, _) }

  predicate isBarrierOut(DataFlow::Node node) { isSink(node, _) }

  predicate observeDiffInformedIncrementalMode() { any() }
}


pragma[inline]
predicate hasBaseType(Expr e, Type base) {
  pragma[only_bind_into](base) = e.getType().(DerivedType).getBaseType()
}


predicate introducesNewField(Class derived, Class base) {
  (
    exists(Field f |
      f.getDeclaringType() = derived and
      derived.getABaseClass+() = base
    )
    or
    introducesNewField(derived.getABaseClass(), base)
  )
}

module CastToPointerArithFlow = DataFlow::GlobalWithState<CastToPointerArithFlowConfig>;

from CastToPointerArithFlow::PathNode source, CastToPointerArithFlow::PathNode sink
where CastToPointerArithFlow::flowPath(source, sink)
select sink, source, sink, "This pointer arithmetic may be done with the wrong type because of $@.",
  source, "this cast"

import cpp
import semmle.code.cpp.rangeanalysis.SimpleRangeAnalysis
import semmle.code.cpp.ir.dataflow.DataFlow


predicate candidateForStmt(
  ForStmt forStmt, Variable v, CrementOperation update, RelationalOperation rel
) {
  update = forStmt.getUpdate() and
  update.getAnOperand() = v.getAnAccess() and
  rel = forStmt.getCondition()
}

pragma[noinline]
predicate candidateDecrForStmt(
  ForStmt forStmt, Variable v, VariableAccess lesserOperand, Expr terminalCondition
) {
  exists(DecrementOperation update, RelationalOperation rel |
    candidateForStmt(forStmt, v, update, rel) and

    terminalCondition = rel.getGreaterOperand() and
    lesserOperand = rel.getLesserOperand() and
    v.getAnAccess() = lesserOperand
  )
}

predicate illDefinedDecrForStmt(
  ForStmt forstmt, Variable v, Expr initialCondition, Expr terminalCondition
) {
  exists(VariableAccess lesserOperand |

    candidateDecrForStmt(forstmt, v, lesserOperand, terminalCondition) and

    v.getAnAssignedValue() = initialCondition and
    DataFlow::localFlowStep+(DataFlow::exprNode(initialCondition), DataFlow::exprNode(lesserOperand)) and

    (
      upperBound(initialCondition) < lowerBound(terminalCondition) and
      (

        v.getUnspecifiedType().(IntegralType).isSigned() or
        initialCondition.getValue().toInt() = 0
      )
      or
      (forstmt.conditionAlwaysFalse() or forstmt.conditionAlwaysTrue())
    )
  )
}

pragma[noinline]
predicate candidateIncrForStmt(
  ForStmt forStmt, Variable v, VariableAccess greaterOperand, Expr terminalCondition
) {
  exists(IncrementOperation update, RelationalOperation rel |
    candidateForStmt(forStmt, v, update, rel) and

    terminalCondition = rel.getLesserOperand() and
    greaterOperand = rel.getGreaterOperand() and
    v.getAnAccess() = greaterOperand
  )
}

predicate illDefinedIncrForStmt(
  ForStmt forstmt, Variable v, Expr initialCondition, Expr terminalCondition
) {
  exists(VariableAccess greaterOperand |

    candidateIncrForStmt(forstmt, v, greaterOperand, terminalCondition) and

    v.getAnAssignedValue() = initialCondition and
    DataFlow::localFlowStep+(DataFlow::exprNode(initialCondition),
      DataFlow::exprNode(greaterOperand)) and

    (
      upperBound(terminalCondition) < lowerBound(initialCondition)
      or
      (forstmt.conditionAlwaysFalse() or forstmt.conditionAlwaysTrue())
    )
  )
}

predicate illDefinedForStmtWrongDirection(
  ForStmt forstmt, Variable v, Expr initialCondition, Expr terminalCondition, boolean isIncr
) {
  illDefinedDecrForStmt(forstmt, v, initialCondition, terminalCondition) and isIncr = false
  or
  illDefinedIncrForStmt(forstmt, v, initialCondition, terminalCondition) and isIncr = true
}

bindingset[b]
private string forLoopdirection(boolean b) {
  if b = true then result = "upward" else result = "downward"
}

bindingset[b]
private string forLoopTerminalConditionRelationship(boolean b) {
  if b = true then result = "lower" else result = "higher"
}

predicate illDefinedForStmt(ForStmt for, string message) {
  exists(boolean isIncr, Variable v, Expr initialCondition, Expr terminalCondition |
    illDefinedForStmtWrongDirection(for, v, initialCondition, terminalCondition, isIncr) and
    if for.conditionAlwaysFalse()
    then
      message =
        "Ill-defined for-loop: a loop using variable \"" + v + "\" counts " +
          forLoopdirection(isIncr) + " from a value (" + initialCondition +
          "), but the terminal condition is always false."
    else
      if for.conditionAlwaysTrue()
      then
        message =
          "Ill-defined for-loop: a loop using variable \"" + v + "\" counts " +
            forLoopdirection(isIncr) + " from a value (" + initialCondition +
            "), but the terminal condition is always true."
      else
        message =
          "Ill-defined for-loop: a loop using variable \"" + v + "\" counts " +
            forLoopdirection(isIncr) + " from a value (" + initialCondition +
            "), but the terminal condition is " + forLoopTerminalConditionRelationship(isIncr) +
            " (" + terminalCondition + ")."
  )
}

from ForStmt forstmt, string message
where illDefinedForStmt(forstmt, message)
select forstmt, message

import cpp
import semmle.code.cpp.controlflow.StackVariableReachability

class UndefReachability extends StackVariableReachability {
  UndefReachability() { this = "UndefReachability" }

  override predicate isSource(ControlFlowNode node, StackVariable v) {
    candidateVariable(v) and
    node = v.getParentScope() and
    not v instanceof Parameter and
    not v.hasInitializer()
  }

  override predicate isSink(ControlFlowNode node, StackVariable v) {
    candidateVariable(v) and
    node = v.getAnAccess()
  }

  override predicate isBarrier(ControlFlowNode node, StackVariable v) {
    node.(AssignExpr).getLValue() = v.getAnAccess()
  }
}

abstract class BooleanControllingAssignment extends AssignExpr {
  abstract predicate isWhitelisted();
}


Expr getComparisonOperand(BinaryLogicalOperation op) { result = op.getAnOperand() }

class BooleanControllingAssignmentInExpr extends BooleanControllingAssignment {
  BooleanControllingAssignmentInExpr() {
    this.getParent() instanceof UnaryLogicalOperation or
    this.getParent() instanceof BinaryLogicalOperation or
    exists(ConditionalExpr c | c.getCondition() = this)
  }

  override predicate isWhitelisted() {
    this.getConversion().(ParenthesisExpr).isParenthesised()
    or




    this.isParenthesised() and
    forex(ComparisonOperation op | op = getComparisonOperand*(this.getParent+()) |
      not op.isParenthesised()
    )
    or






    this.isParenthesised() and
    exists(LogicalAndExpr parent, Variable var, VariableAccess access |
      var = this.getLValue().(VariableAccess).getTarget() and
      access = var.getAnAccess() and
      not access.isUsedAsLValue() and
      parent.getRightOperand() = access.getParent*() and
      parent.getLeftOperand() = this.getParent*()
    )
  }
}

class BooleanControllingAssignmentInStmt extends BooleanControllingAssignment {
  BooleanControllingAssignmentInStmt() {
    exists(IfStmt i | i.getCondition() = this) or
    exists(ForStmt f | f.getCondition() = this) or
    exists(WhileStmt w | w.getCondition() = this) or
    exists(DoStmt d | d.getCondition() = this)
  }

  override predicate isWhitelisted() { this.isParenthesised() }
}


predicate candidateResult(BooleanControllingAssignment ae) {
  ae.getRValue().isConstant() and
  not ae.isWhitelisted() and
  not ae.getRValue() instanceof StringLiteral
}


predicate candidateVariable(Variable v) {
  exists(BooleanControllingAssignment ae |
    candidateResult(ae) and
    ae.getLValue().(VariableAccess).getTarget() = v
  )
}

from BooleanControllingAssignment ae, UndefReachability undef
where
  candidateResult(ae) and
  not ae.isFromUninstantiatedTemplate(_) and
  not undef.reaches(_, ae.getLValue().(VariableAccess).getTarget(), ae.getLValue())
select ae, "Use of '=' where '==' may have been intended."

import cpp
import semmle.code.cpp.commons.Buffer

class SprintfCall extends FunctionCall {
  SprintfCall() { this.getTarget().hasName("sprintf") or this.getTarget().hasName("vsprintf") }

  int getBufferSize() { result = getBufferSize(this.getArgument(0), _) }

  int getMaxConvertedLength() {
    result = this.getArgument(1).(FormatLiteral).getMaxConvertedLength()
  }

  predicate isDangerous() { this.getMaxConvertedLength() > this.getBufferSize() }

  string getDescription() {
    result =
      "This conversion may yield a string of length " + this.getMaxConvertedLength().toString() +
        ", which exceeds the allocated buffer size of " + this.getBufferSize().toString()
  }
}

from SprintfCall c
where c.isDangerous()
select c, c.getDescription()

import cpp
import semmle.code.cpp.ir.IR
import semmle.code.cpp.ir.dataflow.MustFlow
import PathGraph


predicate allocatedType(Type t) {

  t instanceof ArrayType
  or

  t instanceof Class
  or

  allocatedType(t.(TypedefType).getUnderlyingType())
  or

  allocatedType(t.getUnspecifiedType())
}

pragma[noinline]
predicate containsInlineAssembly(Function f) { exists(AsmStmt s | s.getEnclosingFunction() = f) }


VariableAccess commonException() {


  result.getParent().isInMacroExpansion()
  or
  result.getParent() instanceof BuiltInOperation
  or


  result.getActualType() instanceof VoidType and
  result.getParent() instanceof ExprStmt
  or


  containsInlineAssembly(result.getEnclosingFunction())
  or
  exists(Call c | c.getQualifier() = result | c.getTarget().isStatic())
}

predicate isSinkImpl(Instruction sink, VariableAccess va) {
  exists(LoadInstruction load |
    va = load.getUnconvertedResultExpression() and
    not va = commonException() and
    not va.getTarget().(LocalVariable).getFunction().hasErrors() and
    sink = load.getSourceValue()
  )
}

class MustFlow extends MustFlowConfiguration {
  MustFlow() { this = "MustFlow" }

  override predicate isSource(Instruction source) {
    source instanceof UninitializedInstruction and
    exists(Type t | t = source.getResultType() | not allocatedType(t))
  }

  override predicate isSink(Operand sink) { isSinkImpl(sink.getDef(), _) }

  override predicate allowInterproceduralFlow() { none() }

  override predicate isBarrier(Instruction instr) { instr instanceof ChiInstruction }
}

from
  VariableAccess va, LocalVariable v, MustFlow conf, MustFlowPathNode source, MustFlowPathNode sink
where
  conf.hasFlowPath(source, sink) and
  isSinkImpl(sink.getInstruction(), va) and
  v = va.getTarget()
select va, source, sink, "The variable $@ may not be initialized at this access.", v, v.getName()

import cpp


import semmle.code.cpp.valuenumbering.GlobalValueNumbering
import semmle.code.cpp.ir.IR

predicate instructionHasVariable(VariableAddressInstruction vai, StackVariable var, Function f) {
  var = vai.getAstVariable() and
  f = vai.getEnclosingFunction() and

  not vai.getResultType() instanceof PointerToMemberType and

  not f.hasErrors()
}


predicate stackPointerFlowsToUse(Instruction address, VariableAddressInstruction source) {
  address = source and
  instructionHasVariable(source, _, _)
  or
  stackPointerFlowsToUse(address.(CopyInstruction).getSourceValue(), source)
  or
  stackPointerFlowsToUse(address.(ConvertInstruction).getUnary(), source)
  or
  stackPointerFlowsToUse(address.(CheckedConvertOrNullInstruction).getUnary(), source)
  or
  stackPointerFlowsToUse(address.(InheritanceConversionInstruction).getUnary(), source)
  or
  stackPointerFlowsToUse(address.(FieldAddressInstruction).getObjectAddress(), source)
  or
  stackPointerFlowsToUse(address.(PointerOffsetInstruction).getLeft(), source)
}


newtype TGlobalAddress =
  TGlobalVariable(GlobalOrNamespaceVariable v) {

    not v.getUnspecifiedType() instanceof PointerToMemberType
  } or
  TLoad(TGlobalAddress address) {
    address = globalAddress(any(LoadInstruction load).getSourceAddress())
  } or
  TConversion(string kind, TGlobalAddress address, Type fromType, Type toType) {
    kind = "unchecked" and
    exists(ConvertInstruction convert |
      uncheckedConversionTypes(convert, fromType, toType) and
      address = globalAddress(convert.getUnary())
    )
    or
    kind = "checked" and
    exists(CheckedConvertOrNullInstruction convert |
      checkedConversionTypes(convert, fromType, toType) and
      address = globalAddress(convert.getUnary())
    )
    or
    kind = "inheritance" and
    exists(InheritanceConversionInstruction convert |
      inheritanceConversionTypes(convert, fromType, toType) and
      address = globalAddress(convert.getUnary())
    )
  } or
  TFieldAddress(TGlobalAddress address, Field f) {
    exists(FieldAddressInstruction fai |
      fai.getField() = f and
      address = globalAddress(fai.getObjectAddress())
    )
  }

pragma[noinline]
predicate uncheckedConversionTypes(ConvertInstruction convert, Type fromType, Type toType) {
  fromType = convert.getUnary().getResultType() and
  toType = convert.getResultType()
}

pragma[noinline]
predicate checkedConversionTypes(CheckedConvertOrNullInstruction convert, Type fromType, Type toType) {
  fromType = convert.getUnary().getResultType() and
  toType = convert.getResultType()
}

pragma[noinline]
predicate inheritanceConversionTypes(
  InheritanceConversionInstruction convert, Type fromType, Type toType
) {
  fromType = convert.getUnary().getResultType() and
  toType = convert.getResultType()
}

private signature class ConversionInstruction extends UnaryInstruction;

module Conversion<ConversionInstruction I> {
  signature predicate hasTypes(I instr, Type fromType, Type toType);

  module Using<hasTypes/3 project> {
    pragma[nomagic]
    predicate hasOperandAndTypes(I convert, Instruction unary, Type fromType, Type toType) {
      project(convert, fromType, toType) and
      unary = convert.getUnary()
    }
  }
}

pragma[nomagic]
predicate hasObjectAndField(FieldAddressInstruction fai, Instruction object, Field f) {
  fai.getObjectAddress() = object and
  fai.getField() = f
}


TGlobalAddress globalAddress(Instruction instr) {
  result = TGlobalVariable(instr.(VariableAddressInstruction).getAstVariable())
  or
  not instr instanceof LoadInstruction and
  result = globalAddress(instr.(CopyInstruction).getSourceValue())
  or
  exists(LoadInstruction load | instr = load |
    result = TLoad(globalAddress(load.getSourceAddress()))
  )
  or
  exists(Type fromType, Type toType, Instruction unary |
    Conversion<ConvertInstruction>::Using<uncheckedConversionTypes/3>::hasOperandAndTypes(instr,
      unary, fromType, toType) and
    result = TConversion("unchecked", globalAddress(unary), fromType, toType)
  )
  or
  exists(Type fromType, Type toType, Instruction unary |
    Conversion<CheckedConvertOrNullInstruction>::Using<checkedConversionTypes/3>::hasOperandAndTypes(instr,
      unary, fromType, toType) and
    result = TConversion("checked", globalAddress(unary), fromType, toType)
  )
  or
  exists(Type fromType, Type toType, Instruction unary |
    Conversion<InheritanceConversionInstruction>::Using<inheritanceConversionTypes/3>::hasOperandAndTypes(instr,
      unary, fromType, toType) and
    result = TConversion("inheritance", globalAddress(unary), fromType, toType)
  )
  or
  exists(FieldAddressInstruction fai, Instruction object, Field f | instr = fai |
    hasObjectAndField(fai, object, f) and
    result = TFieldAddress(globalAddress(object), f)
  )
  or
  result = globalAddress(instr.(PointerOffsetInstruction).getLeft())
}


StoreInstruction getFirstStore(IRBlock block, TGlobalAddress globalAddress) {
  1 = getStoreRank(result, block, globalAddress)
  or
  not exists(getStoreRank(_, block, globalAddress)) and
  result = getFirstStore(block.getASuccessor(), globalAddress)
}


int getStoreRank(StoreInstruction store, IRBlock block, TGlobalAddress globalAddress) {
  blockStoresToAddress(block, _, store, globalAddress) and
  store =
    rank[result](StoreInstruction anotherStore, int i |
      blockStoresToAddress(_, i, anotherStore, globalAddress)
    |
      anotherStore order by i
    )
}


StoreInstruction getANextStoreTo(StoreInstruction store, TGlobalAddress globalAddress) {
  exists(IRBlock block, int rnk |
    rnk = getStoreRank(store, block, globalAddress) and
    rnk + 1 = getStoreRank(result, block, globalAddress)
  )
  or
  exists(IRBlock block, int rnk, IRBlock succ |
    rnk = getStoreRank(store, block, globalAddress) and
    not rnk + 1 = getStoreRank(_, block, globalAddress) and
    succ = block.getASuccessor() and
    result = getFirstStore(succ, globalAddress)
  )
}


predicate stackAddressEscapes(
  StoreInstruction store, StackVariable var, TGlobalAddress globalAddress, Function f
) {
  globalAddress = globalAddress(store.getDestinationAddress()) and
  exists(VariableAddressInstruction vai |
    instructionHasVariable(pragma[only_bind_into](vai), var, f) and
    stackPointerFlowsToUse(store.getSourceValue(), vai)
  ) and

  not exists(getANextStoreTo(store, globalAddress))
}

predicate blockStoresToAddress(
  IRBlock block, int index, StoreInstruction store, TGlobalAddress globalAddress
) {
  block.getInstruction(index) = store and
  globalAddress = globalAddress(store.getDestinationAddress())
}


predicate globalAddressPointsToStack(
  StoreInstruction store, StackVariable var, CallInstruction call, IRBlock block,
  TGlobalAddress globalAddress, boolean isCallBlock, boolean isStoreBlock
) {
  (
    if blockStoresToAddress(block, _, _, globalAddress)
    then isStoreBlock = true
    else isStoreBlock = false
  ) and
  (
    isCallBlock = true and
    exists(Function f |
      stackAddressEscapes(store, var, globalAddress, f) and
      call.getStaticCallTarget() = f and
      call.getBlock() = block
    )
    or
    isCallBlock = false and
    step(store, var, call, globalAddress, _, block)
  )
}

pragma[inline]
int getInstructionIndex(Instruction instr, IRBlock block) { block.getInstruction(result) = instr }

predicate step(
  StoreInstruction store, StackVariable var, CallInstruction call, TGlobalAddress globalAddress,
  IRBlock pred, IRBlock succ
) {
  exists(boolean isCallBlock, boolean isStoreBlock |

    globalAddressPointsToStack(store, var, call, pred, globalAddress, isCallBlock, isStoreBlock)
  |


    isStoreBlock = false and
    succ.immediatelyPostDominates(pred) and
    pred.immediatelyDominates(succ)
    or
    exists(CallInstruction anotherCall, int anotherCallIndex |
      anotherCall = pred.getInstruction(anotherCallIndex) and
      succ.getFirstInstruction() instanceof EnterFunctionInstruction and
      succ.getEnclosingFunction() = anotherCall.getStaticCallTarget() and
      (if isCallBlock = true then getInstructionIndex(call, _) < anotherCallIndex else any()) and
      (
        if isStoreBlock = true
        then
          forex(int storeIndex | blockStoresToAddress(pred, storeIndex, _, globalAddress) |
            anotherCallIndex < storeIndex
          )
        else any()
      )
    )
  )
}

newtype TPathElement =
  TStore(StoreInstruction store) { globalAddressPointsToStack(store, _, _, _, _, _, _) } or
  TCall(CallInstruction call, IRBlock block) {
    globalAddressPointsToStack(_, _, call, block, _, _, _)
  } or
  TMid(IRBlock block) { step(_, _, _, _, _, block) } or
  TSink(LoadInstruction load, IRBlock block) {
    exists(TGlobalAddress address |
      globalAddressPointsToStack(_, _, _, block, address, _, _) and
      block.getAnInstruction() = load and
      globalAddress(load.getSourceAddress()) = address
    )
  }

class PathElement extends TPathElement {
  StoreInstruction asStore() { this = TStore(result) }

  CallInstruction asCall(IRBlock block) { this = TCall(result, block) }

  predicate isCall(IRBlock block) { exists(this.asCall(block)) }

  IRBlock asMid() { this = TMid(result) }

  LoadInstruction asSink(IRBlock block) { this = TSink(result, block) }

  predicate isSink(IRBlock block) { exists(this.asSink(block)) }

  string toString() {
    result =
      [
        this.asStore().toString(), this.asCall(_).toString(), this.asMid().toString(),
        this.asSink(_).toString()
      ]
  }

  predicate hasLocationInfo(
    string filepath, int startline, int startcolumn, int endline, int endcolumn
  ) {
    this.asStore()
        .getLocation()
        .hasLocationInfo(filepath, startline, startcolumn, endline, endcolumn)
    or
    this.asCall(_)
        .getLocation()
        .hasLocationInfo(filepath, startline, startcolumn, endline, endcolumn)
    or
    this.asMid().getLocation().hasLocationInfo(filepath, startline, startcolumn, endline, endcolumn)
    or
    this.asSink(_)
        .getLocation()
        .hasLocationInfo(filepath, startline, startcolumn, endline, endcolumn)
  }
}

predicate isSink(LoadInstruction load, IRBlock block, int index, TGlobalAddress globalAddress) {
  block.getInstruction(index) = load and
  globalAddress(load.getSourceAddress()) = globalAddress
}

query predicate edges(PathElement pred, PathElement succ) {

  globalAddressPointsToStack(pred.asStore(), _, succ.asCall(_), _, _, _, _)
  or

  pred.isCall(succ.asMid())
  or


  exists(IRBlock block |
    pred.isCall(block) and
    succ.isSink(block)
  )
  or

  step(_, _, _, _, pred.asMid(), succ.asMid())
  or

  succ.isSink(pred.asMid())
}

from
  StoreInstruction store, StackVariable var, LoadInstruction load, CallInstruction call,
  IRBlock block, boolean isCallBlock, TGlobalAddress address, boolean isStoreBlock,
  PathElement source, PathElement sink, int loadIndex
where
  globalAddressPointsToStack(store, var, call, block, address, isCallBlock, isStoreBlock) and
  isSink(load, block, loadIndex, address) and
  (




    if isCallBlock = true
    then

      getInstructionIndex(call, _) < loadIndex
    else any()
  ) and
  (


    if isStoreBlock = true
    then
      forex(int storeIndex | blockStoresToAddress(block, storeIndex, _, address) |
        loadIndex < storeIndex
      )
    else any()
  ) and
  source.asStore() = store and
  sink.asSink(_) = load
select sink, source, sink, "Stack variable $@ escapes at $@ and is used after it has expired.", var,
  var.toString(), store, "this store"

