import semmle.code.cpp.controlflow.Nullness

class StarOperator extends Operator {
  StarOperator() {
    this.hasName("operator*") and
    this.getNumberOfParameters() = 0
  }
}

class IncrementOperator extends Operator {
  IncrementOperator() {
    this.hasName("operator++") and
    this.getNumberOfParameters() = 0
  }
}

class StructureDerefOperator extends Operator {
  StructureDerefOperator() {
    this.hasName("operator->") and
    this.getNumberOfParameters() = 0
  }
}

class SubscriptOperator extends Operator {
  SubscriptOperator() {
    this.hasName("operator[]") and
    this.getNumberOfParameters() = 1
  }
}


abstract class LifetimeIndirectionType extends Type {

  Type getDerefType() {
    result = this.(PointerType).getBaseType()
    or
    result = this.(ReferenceType).getBaseType()
    or
    exists(MemberFunction mf | mf.getDeclaringType() = this |
      result = mf.(StarOperator).getType().getUnspecifiedType().(ReferenceType).getBaseType()
      or
      result = mf.(SubscriptOperator).getType().getUnspecifiedType().(ReferenceType).getBaseType()
      or
      result =
        mf.(StructureDerefOperator).getType().getUnspecifiedType().(PointerType).getBaseType()
      or
      mf.getName() = "begin" and
      result = mf.getType().(LifetimePointerType).getDerefType()
    )
  }
}


class LifetimeOwnerType extends LifetimeIndirectionType {
  LifetimeOwnerType() {

    this instanceof LifetimeSharedOwnerType
    or

    (
      this instanceof ContainerType
      or
      exists(StarOperator mf | mf.getDeclaringType() = this)
    ) and

    exists(Destructor d |
      d.getDeclaringType() = this and
      not d.isCompilerGenerated()
    )
    or

    this.getUnspecifiedType() instanceof LifetimeOwnerType
    or

    this.(Class).getAField().getType() instanceof LifetimeOwnerType
    or

    exists(ClassDerivation cd |
      cd = this.(Class).getADerivation() and
      cd.getBaseClass() instanceof LifetimeOwnerType and
      cd.getASpecifier().hasName("public")
    )
    or


    this.(Class)
        .hasQualifiedName("std",
          ["stack", "queue", "priority_queue", "optional", "variant", "any", "regex"])
    or

    this.getAnAttribute().getName().matches("gsl::Owner%")
  }
}


class ContainerType extends Class {
  ContainerType() {



    this.getAMemberFunction().getName() = "begin" and
    this.getAMemberFunction().getName() = "end" and
    this.getAMemberFunction().getName() = "size"
    or


    exists(TemplateClass tc |
      this.isConstructedFrom(tc) and
      tc instanceof ContainerType
    )
  }
}


class LifetimeSharedOwnerType extends Type {
  LifetimeSharedOwnerType() {



    exists(StarOperator mf | mf.getDeclaringType() = this) and

    exists(Destructor d |
      d.getDeclaringType() = this and
      not d.isCompilerGenerated()
    ) and

    exists(CopyConstructor cc | cc.getDeclaringType() = this and not cc.isDeleted()) and
    exists(CopyAssignmentOperator cc | cc.getDeclaringType() = this and not cc.isDeleted())
    or


    exists(TemplateClass tc |
      this.(Class).isConstructedFrom(tc) and
      tc instanceof LifetimeSharedOwnerType
    )
    or

    this.getUnspecifiedType() instanceof LifetimeSharedOwnerType
    or

    this.(Class).getAField().getType() instanceof LifetimeSharedOwnerType
    or

    exists(ClassDerivation cd |
      cd = this.(Class).getADerivation() and
      cd.getBaseClass() instanceof LifetimeSharedOwnerType and
      cd.getASpecifier().hasName("public")
    )
    or


    this.(Class).hasQualifiedName("std", "shared_future")
    or

    this.getAnAttribute().getName().matches("gsl::SharedOwner%")
  }
}


class IteratorType extends Type {
  IteratorType() {

    exists(StarOperator mf |
      mf.getDeclaringType() = this and mf.getType().getUnspecifiedType() instanceof ReferenceType
    ) and
    exists(IncrementOperator op |
      op.getDeclaringType() = this and op.getType().(ReferenceType).getBaseType() = this
    )
    or

    this.getUnspecifiedType() instanceof IteratorType
  }
}


class LifetimePointerType extends LifetimeIndirectionType {
  LifetimePointerType() {
    this instanceof IteratorType
    or
    this instanceof PointerType
    or
    this instanceof ReferenceType
    or

    this instanceof LifetimeSharedOwnerType and
    not this instanceof LifetimeOwnerType
    or
    this.(Class).hasQualifiedName("std", "reference_wrapper")
    or
    exists(Class vectorBool, UserType reference |
      vectorBool.hasQualifiedName("std", "vector") and
      vectorBool.getATemplateArgument() instanceof BoolType and
      reference.hasName("reference") and
      reference.getDeclaringType() = vectorBool and
      this = reference.getUnderlyingType()
    )
    or

    this.getUnspecifiedType() instanceof LifetimePointerType
    or

    this.(Class).getAField().getType() instanceof LifetimePointerType
    or

    exists(ClassDerivation cd |
      cd = this.(Class).getADerivation() and
      cd.getBaseClass() instanceof LifetimePointerType and
      cd.getASpecifier().hasName("public")
    )
    or

    this.getAnAttribute().getName().matches("gsl::Pointer%")
  }
}


class FullExpr extends Expr {
  FullExpr() {

    not this.getParent() instanceof Expr
    or

    this.isUnevaluated()
  }
}


FullExpr getTemporaryObjectExprScope(TemporaryObjectExpr toe) {
  result = toe.getUnconverted().getParent*()
}


private newtype TLifetimeLocalVariable =
  TLocalScopeVariable(LocalScopeVariable lsv) { not lsv.isStatic() } or
  TTemporaryObject(TemporaryObjectExpr toe)




class LifetimeLocalVariable extends TLifetimeLocalVariable {
  string toString() { none() } 

  Type getType() { none() }
}


class LifetimeLocalScopeVariable extends TLocalScopeVariable, LifetimeLocalVariable {
  LocalScopeVariable getVariable() { this = TLocalScopeVariable(result) }

  override Type getType() { result = this.getVariable().getType() }

  override string toString() { result = this.getVariable().toString() }
}


class LifetimeTemporaryObject extends TTemporaryObject, LifetimeLocalVariable {
  TemporaryObjectExpr getTemporaryObjectExpr() { this = TTemporaryObject(result) }

  override Type getType() { result = this.getTemporaryObjectExpr().getType() }

  override string toString() { result = this.getTemporaryObjectExpr().toString() }
}

newtype TInvalidReason =

  TUninitialized(DeclStmt ds, Variable v) { ds.getADeclaration() = v } or

  TVariableOutOfScope(LocalScopeVariable v, ControlFlowNode cfn) { goesOutOfScopeAt(v, cfn) } or

  TTemporaryOutOfScope(TemporaryObjectExpr toe) or

  TOwnerModified(FunctionCall fc)


class InvalidReason extends TInvalidReason {

  predicate isBeforeLifetime() { this instanceof TUninitialized }


  predicate isAfterLifetime() { not this.isBeforeLifetime() }


  string getDescription() {
    exists(DeclStmt ds, Variable v |
      this = TUninitialized(ds, v) and
      result = "variable " + v.getName() + " was never initialized"
    )
    or
    exists(LocalScopeVariable v, ControlFlowNode cfn |
      this = TVariableOutOfScope(v, cfn) and
      result = "variable " + v.getName() + " went out of scope"
    )
    or
    exists(TemporaryObjectExpr toe |
      this = TTemporaryOutOfScope(toe) and
      result = "temporary object went out of scope"
    )
    or
    exists(FunctionCall fc |
      this = TOwnerModified(fc) and
      result = "owner type was modified"
    )
  }

  string toString() { result = this.getDescription() }


  private Element getExplanatoryElement() {
    exists(DeclStmt ds |
      this = TUninitialized(ds, _) and
      result = ds
    )
    or
    exists(ControlFlowNode cfn |
      this = TVariableOutOfScope(_, cfn) and
      result = cfn
    )
    or
    exists(TemporaryObjectExpr toe |
      this = TTemporaryOutOfScope(toe) and
      result = getTemporaryObjectExprScope(toe)
    )
    or
    exists(FunctionCall fc |
      this = TOwnerModified(fc) and
      result = fc
    )
  }


  predicate hasMessage(string message, Element explanation, string explanationDesc) {
    message = "because the " + this.getDescription() + " $@." and
    explanation = this.getExplanatoryElement() and
    explanationDesc = "here"
  }
}


newtype TNullReason =

  TNullAssignment(NullValue e)

class NullReason extends TNullReason {

  string getDescription() {
    exists(NullValue nv |
      this = TNullAssignment(nv) and
      result = "null value was assigned"
    )
  }

  string toString() { result = this.getDescription() }
}


newtype TPSetEntry =

  PSetVar(LifetimeLocalVariable lv) or

  PSetOwner(LifetimeLocalVariable lv, int level) {
    level = [0 .. 2] and lv.getType() instanceof LifetimeOwnerType
  } or

  PSetGlobal() or

  PSetNull(NullReason nr) or

  PSetInvalid(InvalidReason ir) or

  PSetUnknown()


class PSetEntry extends TPSetEntry {
  string toString() {
    exists(LifetimeLocalVariable lv |
      this = PSetVar(lv) and
      result = "Var(" + lv.toString() + ")"
    )
    or
    this = PSetGlobal() and result = "global"
    or
    exists(LifetimeLocalVariable lv, int level |
      this = PSetOwner(lv, level) and
      result = "Owner(" + lv.toString() + "," + level + ")"
    )
    or
    exists(NullReason nr | this = PSetNull(nr) and result = "null because" + nr)
    or
    exists(InvalidReason ir | this = PSetInvalid(ir) and result = "invalid because " + ir)
    or
    this = PSetUnknown() and result = "unknown"
  }
}


predicate pointsToMap(ControlFlowNode cfn, LifetimeLocalVariable lv, PSetEntry ps) {
  if isPSetReassigned(cfn, lv)
  then ps = getAnAssignedPSetEntry(cfn, lv)
  else

    exists(ControlFlowNode pred, PSetEntry prevPSet |
      pred = cfn.getAPredecessor() and
      pointsToMap(pred, lv, prevPSet) and

      not exists(AnalysedExpr ae |
        ps = PSetNull(_) and
        cfn = ae.getNonNullSuccessor(lv.(LifetimeLocalScopeVariable).getVariable())
      ) and

      not goesOutOfScopeAt(lv.(LifetimeLocalScopeVariable).getVariable(), cfn)
    |


      ps = prevPSet and
      not exists(getAnInvalidation(prevPSet, cfn))
      or

      ps = getAnInvalidation(prevPSet, cfn)
    )
}

private predicate isPSetReassigned(ControlFlowNode cfn, LifetimeLocalVariable lv) {
  exists(DeclStmt ds |
    cfn = ds and
    ds.getADeclaration() = lv.(LifetimeLocalScopeVariable).getVariable() and
    lv.getType() instanceof PointerType
  )
  or
  exists(TemporaryObjectExpr toe |
    toe = lv.(LifetimeTemporaryObject).getTemporaryObjectExpr() and
    cfn = toe
  )
  or

  cfn = lv.(LifetimeLocalScopeVariable).getVariable().getAnAssignedValue()
  or

  exists(Call fc, AddressOfExpr aoe |
    cfn = aoe and
    fc.getAnArgument() = aoe and
    lv.(LifetimeLocalScopeVariable).getVariable() = aoe.getOperand().(VariableAccess).getTarget()
  )
}


private PSetEntry getAnAssignedPSetEntry(ControlFlowNode cfn, LifetimeLocalVariable lv) {
  exists(DeclStmt ds |
    cfn = ds and
    ds.getADeclaration() = lv.(LifetimeLocalScopeVariable).getVariable()
  |
    lv.getType() instanceof PointerType and
    result = PSetInvalid(TUninitialized(ds, lv.(LifetimeLocalScopeVariable).getVariable()))
  )
  or
  exists(TemporaryObjectExpr toe |
    toe = lv.(LifetimeTemporaryObject).getTemporaryObjectExpr() and
    cfn = toe and
    result = PSetVar(lv)
  )
  or

  exists(Expr assign |
    assign = lv.(LifetimeLocalScopeVariable).getVariable().getAnAssignedValue() and
    cfn = assign
  |
    if isKnownAssignmentType(assign)
    then knownAssignmentType(assign, result)
    else result = PSetUnknown()
  )
  or

  exists(Call fc, AddressOfExpr aoe |
    cfn = aoe and
    fc.getAnArgument() = aoe and
    lv.(LifetimeLocalScopeVariable).getVariable() = aoe.getOperand().(VariableAccess).getTarget() and
    result = PSetUnknown()
  )
}

predicate isKnownAssignmentType(Expr assign) {
  assign = any(LocalScopeVariable lv).getAnAssignedValue() and
  (
    exists(Variable v | v = assign.(AddressOfExpr).getOperand().(VariableAccess).getTarget() |
      v instanceof LocalScopeVariable
      or
      v instanceof GlobalVariable
    )
    or

    exists(VariableAccess va |
      va = assign and
      va.getTarget().(LocalScopeVariable).getType() instanceof LifetimePointerType
    )
    or
    assign instanceof NullValue
    or
    exists(FunctionCall fc |
      assign = fc and
      fc.getNumberOfArguments() = 0 and
      fc.getType() instanceof LifetimePointerType
    |

      exists(LifetimeLocalVariable lv |
        lv = TTemporaryObject(fc.getQualifier().getConversion())
        or
        lv = TLocalScopeVariable(fc.getQualifier().(VariableAccess).getTarget())
      |
        lv.getType() instanceof LifetimePointerType
        or
        lv.getType() instanceof LifetimeOwnerType
      )
    )
  )
}


predicate knownAssignmentType(Expr assign, PSetEntry ps) {
  assign = any(LocalScopeVariable lv).getAnAssignedValue() and
  (

    exists(Variable v | v = assign.(AddressOfExpr).getOperand().(VariableAccess).getTarget() |
      v instanceof LocalScopeVariable and
      (



        if v.getType() instanceof ReferenceType
        then
          pointsToMap(assign.getAPredecessor(),
            any(LifetimeLocalScopeVariable lv | lv.getVariable() = v), ps)
        else

          ps = PSetVar(TLocalScopeVariable(v))
      )
      or




      (v instanceof GlobalVariable or v.getType() instanceof ReferenceType) and
      ps = PSetGlobal()
    )
    or

    exists(VariableAccess va |
      va = assign and
      va.getTarget().(LocalScopeVariable).getType() instanceof LifetimePointerType and

      pointsToMap(assign.getAPredecessor(),
        any(LifetimeLocalScopeVariable lv | lv.getVariable() = va.getTarget()), ps)
    )
    or



    assign instanceof NullValue and ps = PSetNull(TNullAssignment(assign))
    or
    exists(FunctionCall fc |
      assign = fc and


      not assign.getFullyConverted() instanceof ReferenceDereferenceExpr and
      fc.getNumberOfArguments() = 0 and
      fc.getType() instanceof LifetimePointerType
    |

      exists(LifetimeLocalVariable lv |
        lv = TTemporaryObject(fc.getQualifier().getConversion())
        or
        lv = TLocalScopeVariable(fc.getQualifier().(VariableAccess).getTarget())
      |
        ps = PSetVar(lv) and lv.getType() instanceof LifetimePointerType
        or
        ps = PSetOwner(lv, 0) and lv.getType() instanceof LifetimeOwnerType
      )
    )
  )
}


predicate goesOutOfScopeAt(LocalScopeVariable lv, ControlFlowNode cfn) {
  exists(BlockStmt scope |
    scope = lv.getParentScope() and
    scope.getAChild+() = cfn.getAPredecessor().getEnclosingStmt() and
    not scope.getAChild+() = cfn.getEnclosingStmt()
  )
}

PSetInvalid getAnInvalidation(PSetEntry ps, ControlFlowNode cfn) {
  exists(LifetimeLocalScopeVariable lv | ps = PSetVar(lv) |
    result = PSetInvalid(TVariableOutOfScope(lv.getVariable(), cfn))
  )
  or
  exists(LifetimeLocalScopeVariable lv | ps = PSetOwner(lv, _) |
    result = PSetInvalid(TVariableOutOfScope(lv.getVariable(), cfn))
    or
    exists(FunctionCall fc |
      fc = cfn and
      fc.getQualifier() = lv.getVariable().getAnAccess() and
      not fc.getTarget() instanceof ConstMemberFunction and

      not fc.getTarget().hasName(["begin", "end"]) and
      result = PSetInvalid(TOwnerModified(fc))
    )
  )
  or

  exists(LifetimeTemporaryObject lto |
    ps = PSetVar(lto)
    or
    ps = PSetOwner(lto, _)
  |
    cfn = lto.getTemporaryObjectExpr().getUnconverted().getParent*().(FullExpr).getASuccessor() and
    result = PSetInvalid(TTemporaryOutOfScope(lto.getTemporaryObjectExpr()))
  )
}


class InvalidDereference extends VariableAccess {
  InvalidReason ir;

  InvalidDereference() {

    exists(LocalScopeVariable lv |
      lv = this.getTarget() and
      pointsToMap(this, TLocalScopeVariable(lv), PSetInvalid(ir))
    )
  }


  InvalidReason getAnInvalidReason() { result = ir }
}

from
  InvalidDereference e, Element explanation, string explanationDesc, InvalidReason ir,
  string invalidMessage
where
  ir = e.getAnInvalidReason() and
  ir.isAfterLifetime() and
  ir.hasMessage(invalidMessage, explanation, explanationDesc)
select e,
  e.(VariableAccess).getTarget().getName() + " is dereferenced here but accesses invalid memory " +
    invalidMessage, explanation, explanationDesc

import cpp
import semmle.code.cpp.models.interfaces.Allocation
import semmle.code.cpp.ir.dataflow.DataFlow
import MultToAlloc::PathGraph

module MultToAllocConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node node) {

    exists(MulExpr me |
      me = node.asExpr() and
      forall(Expr e | e = me.getAnOperand() | not exists(e.getValue()))
    )
  }

  predicate isSink(DataFlow::Node node) {

    node.asExpr() = any(HeuristicAllocationExpr ae).getSizeExpr().getAChild*()
  }

  predicate observeDiffInformedIncrementalMode() { any() }
}

module MultToAlloc = DataFlow::Global<MultToAllocConfig>;

from MultToAlloc::PathNode source, MultToAlloc::PathNode sink
where MultToAlloc::flowPath(source, sink)
select sink, source, sink,
  "Potentially overflowing value from $@ is used in the size of this allocation.", source,
  "multiplication"

import cpp


string encryptionWord() {
  exists(string word |


    word =
      [
        "Crypt", "Cipher", "Aes", "Rijndael",

        "(?<!C)Rc[0-9]", "(?<!Cha|Unive)Rsa", "Blowfish", "Twofish", "Idea", "Kyber", "(?<!V)Aria",

        "Camellia",

        "Chacha", "ChaCha", "Poly[0-9]", "Ripemd", "Whirlpool", "Sbox", "SBox", "Cblock", "CBlock",
        "Sub.?Bytes?", "Mix.?Columns?", "ECDH", "ECDSA", "EdDSA", "ECMQV", "ECQV", "Curve[0-9][0-9]"
      ] and
    (
      result = word or
      result = word.toLowerCase() + "(?![a-z])" or 
      result = word.toUpperCase() + "(?![A-Z])" 
    )
  )
}


predicate likelyEncryptionFunction(Function f) {
  exists(string fName | fName = f.getName() |
    fName.regexpMatch(".*(" + concat(encryptionWord(), "|") + ").*")
  )
}


predicate computeHeuristicType(Type t) {
  t instanceof IntegralType or
  computeHeuristicType(t.(ArrayType).getBaseType().getUnspecifiedType())
}


predicate computeHeuristic(Expr e) {
  (
    e instanceof BitwiseXorExpr or
    e instanceof AssignXorExpr or
    e instanceof LShiftExpr or
    e instanceof AssignLShiftExpr or
    e instanceof RShiftExpr or
    e instanceof AssignRShiftExpr or
    e instanceof ArrayExpr
  ) and
  computeHeuristicType(e.getUnspecifiedType())
}


string encryptionLibraryName() {
  result =
    [
      "libssh", "openssl", "boringssl", "mbed", "libsodium", "libsrtp", "third.?party", "library",
      "deps"
    ]
}


predicate isLibrary(File f) {
  f.getAbsolutePath().regexpMatch("(?i).*(" + concat(encryptionLibraryName(), "|") + ").*")
  or

  not exists(f.getFile().getRelativePath())
}

from Function f, int amount
where
  likelyEncryptionFunction(f) and
  amount = strictcount(Expr e | computeHeuristic(e) and e.getEnclosingFunction() = f) and
  amount >= 8 and
  not isLibrary(f.getFile())
select f,
  "This function, \"" + f.getName() +
    "\", may be a custom implementation of a cryptographic primitive."

import cpp
import semmle.code.cpp.ir.dataflow.TaintTracking
import semmle.code.cpp.security.FlowSources
import WordexpTaint::PathGraph


private class WordexpFunction extends Function {
  WordexpFunction() { this.hasGlobalName("wordexp") }
}


private predicate isCommandSubstitutionDisabled(FunctionCall fc) {
  fc.getArgument(2).getValue().toInt().bitAnd(4) = 4

}


module WordexpTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) { source instanceof FlowSource }

  predicate isSink(DataFlow::Node sink) {
    exists(FunctionCall fc | fc.getTarget() instanceof WordexpFunction |
      fc.getArgument(0) = sink.asIndirectArgument(1) and
      not isCommandSubstitutionDisabled(fc)
    )
  }

  predicate isBarrier(DataFlow::Node node) {
    node.asExpr().getUnspecifiedType() instanceof IntegralType
  }

  predicate observeDiffInformedIncrementalMode() { any() }

  Location getASelectedSourceLocation(DataFlow::Node source) { none() }
}

module WordexpTaint = TaintTracking::Global<WordexpTaintConfig>;

from WordexpTaint::PathNode sourceNode, WordexpTaint::PathNode sinkNode
where WordexpTaint::flowPath(sourceNode, sinkNode)
select sinkNode.getNode(), sourceNode, sinkNode,
  "Using user-supplied data in a `wordexp` command, without disabling command substitution, can make code vulnerable to command injection."

import cpp
import semmle.code.cpp.valuenumbering.GlobalValueNumbering

class CopyFromUserFunctionCall extends FunctionCall {
  CopyFromUserFunctionCall() {
    this.getTarget().getName() = "copy_from_user" and
    not this.getArgument(1) instanceof AddressOfExpr
  }




  predicate readFromSameUserModePointer(CopyFromUserFunctionCall another) {
    globalValueNumber(this.getArgument(1)) = globalValueNumber(another.getArgument(1))
  }
}

from CopyFromUserFunctionCall p1, CopyFromUserFunctionCall p2
where
  not p1 = p2 and
  p1.readFromSameUserModePointer(p2) and
  exists(IfStmt ifStmt |
    p1.getBasicBlock().getAFalseSuccessor*() = ifStmt.getBasicBlock() and
    ifStmt.getBasicBlock().getAFalseSuccessor*() = p2.getBasicBlock()
  ) and
  not exists(AssignPointerAddExpr assignPtrAdd |
    globalValueNumber(p1.getArgument(1)) = globalValueNumber(assignPtrAdd.getLValue()) and
    p1.getBasicBlock().getAFalseSuccessor*() = assignPtrAdd.getBasicBlock()
  )
select p2, "Double fetch vulnerability. First fetch was $@.", p1, p1.toString()

import cpp


class DangerousWhileLoop extends WhileStmt {
  Declaration dl;

  DangerousWhileLoop() {
    this = dl.getParentScope().(BlockStmt).getParent*() and
    exists(Expr exp |
      exp = this.getCondition().getAChild*() and
      not exp instanceof PointerFieldAccess and
      not exp instanceof ValueFieldAccess and
      exp.(VariableAccess).getTarget().getName() = dl.getName() and
      not exp.getParent*() instanceof FunctionCall
    )
  }

  Declaration getDeclaration() { result = dl }


  predicate isUseThisVariable() {
    exists(Variable v |
      this.getCondition().getAChild*().(VariableAccess).getTarget() = v and
      (
        exists(Assignment aexp |
          this = aexp.getEnclosingStmt().getParentStmt*() and
          (
            aexp.getLValue().(ArrayExpr).getArrayBase().(VariableAccess).getTarget() = v
            or
            aexp.getLValue().(VariableAccess).getTarget() = v
          )
        )
        or
        exists(CrementOperation crm |
          this = crm.getEnclosingStmt().getParentStmt*() and
          crm.getOperand().(VariableAccess).getTarget() = v
        )
      )
    )
  }
}

from DangerousWhileLoop lp
where not lp.isUseThisVariable()
select lp.getDeclaration(), "A variable with this name is used in the $@ condition.", lp, "loop"

import cpp
import semmle.code.cpp.ir.dataflow.DataFlow


class SystemCallFunction extends Function {
  SystemCallFunction() {
    exists(MacroInvocation m |
      m.getMacro().getName().matches("SYSCALL\\_DEFINE%") and
      this = m.getEnclosingFunction()
    )
  }
}


class SystemCallSource extends DataFlow::Node {
  SystemCallSource() {
    exists(FunctionCall fc |
      fc.getTarget() instanceof SystemCallFunction and
      (
        this.asDefiningArgument() = fc.getAnArgument().getAChild*() or
        this.asExpr() = fc
      )
    )
  }
}


class WriteAccessCheckMacro extends Macro {
  VariableAccess va;

  WriteAccessCheckMacro() {
    this.getName() = ["user_write_access_begin", "user_access_begin", "access_ok"] and
    va.getEnclosingElement() = this.getAnInvocation().getAnExpandedElement()
  }

  VariableAccess getArgument() { result = va }
}


class UnSafePutUserMacro extends Macro {
  PointerDereferenceExpr writeUserPtr;

  UnSafePutUserMacro() {
    this.getName() = "unsafe_put_user" and
    writeUserPtr.getEnclosingElement() = this.getAnInvocation().getAnExpandedElement()
  }

  Expr getUserModePtr() {
    result = writeUserPtr.getOperand().(AddressOfExpr).getOperand().(FieldAccess).getQualifier() or
    result = writeUserPtr.getOperand()
  }
}

class ExploitableUserModePtrParam extends SystemCallSource {
  ExploitableUserModePtrParam() {
    exists(UnSafePutUserMacro unsafePutUser |
      DataFlow::localFlow(this, DataFlow::exprNode(unsafePutUser.getUserModePtr()))
    ) and
    not exists(WriteAccessCheckMacro writeAccessCheck |
      DataFlow::localFlow(this, DataFlow::exprNode(writeAccessCheck.getArgument()))
    )
  }
}

from ExploitableUserModePtrParam p
select p, "This 'unsafe_put_user' writes a user-mode pointer without a security check."

import cpp
import semmle.code.cpp.controlflow.Guards
import semmle.code.cpp.valuenumbering.HashCons


class CallMayNotReturn extends FunctionCall {
  CallMayNotReturn() {

    not exists(this.(ControlFlowNode).getASuccessor())
    or

    exists(CallMayNotReturn exit | this.getTarget() = exit.getEnclosingFunction())
  }
}


class ReallocCallLeak extends FunctionCall {
  Variable v;

  ReallocCallLeak() {
    exists(AssignExpr ex |
      this.getTarget().hasGlobalOrStdName("realloc") and
      this = ex.getRValue() and
      hashCons(ex.getLValue()) = hashCons(this.getArgument(0)) and
      v.getAnAccess() = this.getArgument(0)
    )
  }


  predicate mayHandleByTermination() {
    exists(GuardCondition guard, CallMayNotReturn exit |
      this.(ControlFlowNode).getASuccessor*() = guard and
      guard.getAChild*() = v.getAnAccess() and
      guard.controls(exit.getBasicBlock(), _)
    )
  }
}

from ReallocCallLeak rcl
where not rcl.mayHandleByTermination()
select rcl, "Possible loss of original pointer on unsuccessful call to 'realloc'."

import cpp
import semmle.code.cpp.security.FlowSources
import DecompressionBomb

predicate isSink(FunctionCall fc, DataFlow::Node sink) {
  exists(DecompressionFunction f | fc.getTarget() = f |
    fc.getArgument(f.getArchiveParameterIndex()) = [sink.asExpr(), sink.asIndirectExpr()]
  )
}

module DecompressionTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) { source instanceof FlowSource }

  predicate isSink(DataFlow::Node sink) { isSink(_, sink) }

  predicate isAdditionalFlowStep(DataFlow::Node node1, DataFlow::Node node2) {
    any(DecompressionFlowStep s).isAdditionalFlowStep(node1, node2)
  }

  predicate observeDiffInformedIncrementalMode() { any() }

  Location getASelectedSourceLocation(DataFlow::Node source) { none() }

  Location getASelectedSinkLocation(DataFlow::Node sink) {
    exists(FunctionCall fc | result = [sink.getLocation(), fc.getLocation()] | isSink(fc, sink))
  }
}

module DecompressionTaint = TaintTracking::Global<DecompressionTaintConfig>;

import DecompressionTaint::PathGraph

from DecompressionTaint::PathNode source, DecompressionTaint::PathNode sink, FunctionCall fc
where DecompressionTaint::flowPath(source, sink) and isSink(fc, sink.getNode())
select sink.getNode(), source, sink, "The decompression output of $@ is not limited", fc,
  fc.getTarget().getName()

import cpp
import semmle.code.cpp.valuenumbering.GlobalValueNumbering


class DangerousBitOperations extends BinaryBitwiseOperation {
  FunctionCall bfc;


  DangerousBitOperations() {
    bfc = this.getRightOperand() and
    not this.getParent*() instanceof Assignment and
    not this.getParent*() instanceof Initializer and
    not this.getParent*() instanceof ReturnStmt and
    not this.getParent*() instanceof EqualityOperation and
    not this.getParent*() instanceof UnaryLogicalOperation and
    not this.getParent*() instanceof BinaryLogicalOperation and
    not this.getAChild*() instanceof BitwiseXorExpr and
    not this.getAChild*() instanceof LShiftExpr and
    not this.getAChild*() instanceof RShiftExpr
  }


  predicate useInLogicalOperations() {
    exists(BinaryLogicalOperation blop, Expr exp |
      blop.getAChild*() = exp and
      exp.(FunctionCall).getTarget() = bfc.getTarget() and
      not exp.getParent() instanceof ComparisonOperation and
      not exp.getParent() instanceof BinaryBitwiseOperation
    )
  }


  predicate useInOtherCalls() {
    bfc.hasQualifier() or
    bfc.getTarget() instanceof Operator or
    exists(FunctionCall fc | fc.getAnArgument().getAChild*() = this) or
    bfc.getTarget() instanceof BuiltInFunction
  }


  predicate dangerousArgumentChecking() {
    not this.getLeftOperand() instanceof Call and
    globalValueNumber(this.getLeftOperand().getAChild*()) = globalValueNumber(bfc.getAnArgument())
  }


  predicate functionCallsInBitsExpression() {
    this.getLeftOperand().getAChild*() instanceof FunctionCall
  }
}

from DangerousBitOperations dbo
where
  not dbo.useInOtherCalls() and
  dbo.useInLogicalOperations() and
  (not dbo.functionCallsInBitsExpression() or dbo.dangerousArgumentChecking())
select dbo, "This bitwise operation appears in a context where a Boolean operation is expected."

import cpp
import semmle.code.cpp.valuenumbering.HashCons
import semmle.code.cpp.valuenumbering.GlobalValueNumbering


class UsingWhileAfterWhile extends WhileStmt {

  UsingWhileAfterWhile() {
    exists(WhileStmt wh1 |
      wh1.getStmt().getAChild*().(BreakStmt).(ControlFlowNode).getASuccessor().getASuccessor() =
        this and
      hashCons(wh1.getCondition()) = hashCons(this.getCondition()) and
      this.getStmt() instanceof EmptyStmt
    )
    or
    exists(ForStmt fr1 |
      fr1.getStmt().getAChild*().(BreakStmt).(ControlFlowNode).getASuccessor().getASuccessor() =
        this and
      hashCons(fr1.getCondition()) = hashCons(this.getCondition()) and
      this.getStmt() instanceof EmptyStmt
    )
  }
}


class UsingArithmeticInComparison extends BinaryArithmeticOperation {

  UsingArithmeticInComparison() {
    this.getParent*() instanceof IfStmt and
    not this.getAChild*().isConstant() and
    not this.getParent*() instanceof Call and
    not this.getParent*() instanceof AssignExpr and
    not this.getParent*() instanceof ArrayExpr and
    not this.getParent*() instanceof RemExpr and
    not this.getParent*() instanceof AssignBitwiseOperation and
    not this.getParent*() instanceof AssignArithmeticOperation and
    not this.getParent*() instanceof EqualityOperation and
    not this.getParent*() instanceof RelationalOperation
  }


  predicate insideTheLoop() { exists(Loop lp | lp.getStmt().getAChild*() = this.getParent*()) }


  predicate workingWithValue() {
    this.getParent*() instanceof BinaryBitwiseOperation or
    this.getParent*() instanceof NotExpr
  }


  predicate workingWithPointer() {
    this.getAChild*().getFullyConverted().getType() instanceof DerivedType
  }


  predicate compareWithZero() {
    exists(Expr exp |
      exp instanceof ComparisonOperation and
      (
        globalValueNumber(exp.getAChild*()) = globalValueNumber(this) or
        hashCons(exp.getAChild*()) = hashCons(this)
      ) and
      (
        exp.(ComparisonOperation).getLeftOperand().getValue() = "0" or
        exp.(ComparisonOperation).getRightOperand().getValue() = "0"
      )
    )
  }


  predicate compareWithOutZero() {
    exists(Expr exp |
      exp instanceof ComparisonOperation and
      (
        globalValueNumber(exp.getAChild*()) = globalValueNumber(this) or
        hashCons(exp.getAChild*()) = hashCons(this)
      )
    )
  }
}

from Expr exp
where
  exp instanceof UsingArithmeticInComparison and
  not exp.(UsingArithmeticInComparison).workingWithValue() and
  not exp.(UsingArithmeticInComparison).workingWithPointer() and
  not exp.(UsingArithmeticInComparison).insideTheLoop() and
  not exp.(UsingArithmeticInComparison).compareWithZero() and
  exp.(UsingArithmeticInComparison).compareWithOutZero()
  or
  exists(WhileStmt wst | wst instanceof UsingWhileAfterWhile and exp = wst.getCondition())
select exp, "This expression needs your attention."

import cpp

predicate argumentMayBeRoot(Expr e) {
  e.getValue() = "0" or
  e.(VariableAccess).getTarget().getName().toLowerCase().matches("%root%")
}

class SetuidLikeFunctionCall extends FunctionCall {
  SetuidLikeFunctionCall() {
    (this.getTarget().hasGlobalName("setuid") or this.getTarget().hasGlobalName("setresuid")) and

    not argumentMayBeRoot(this.getArgument(0))
  }
}

class SetuidLikeWrapperCall extends FunctionCall {
  SetuidLikeFunctionCall baseCall;

  SetuidLikeWrapperCall() {
    this = baseCall
    or
    exists(SetuidLikeWrapperCall fc |
      this.getTarget() = fc.getEnclosingFunction() and
      baseCall = fc.getBaseCall()
    )
  }

  SetuidLikeFunctionCall getBaseCall() { result = baseCall }
}

class CallBeforeSetuidFunctionCall extends FunctionCall {
  CallBeforeSetuidFunctionCall() {
    this.getTarget()
        .hasGlobalName([
            "setgid", "setresgid",


            "initgroups", "setgroups"
          ]) and

    not argumentMayBeRoot(this.getArgument(0))
  }
}

class CallBeforeSetuidWrapperCall extends FunctionCall {
  CallBeforeSetuidFunctionCall baseCall;

  CallBeforeSetuidWrapperCall() {
    this = baseCall
    or
    exists(CallBeforeSetuidWrapperCall fc |
      this.getTarget() = fc.getEnclosingFunction() and
      baseCall = fc.getBaseCall()
    )
  }

  CallBeforeSetuidFunctionCall getBaseCall() { result = baseCall }
}

predicate setuidBeforeSetgid(
  SetuidLikeWrapperCall setuidWrapper, CallBeforeSetuidWrapperCall setgidWrapper
) {
  setgidWrapper.getAPredecessor+() = setuidWrapper
}

predicate isAccessed(FunctionCall fc) {
  exists(Variable v | v.getAnAssignedValue() = fc)
  or
  exists(Operation c | fc = c.getAChild() | c.isCondition())
  or

  fc.hasExplicitConversion()
}

from Function func, CallBeforeSetuidFunctionCall fc, SetuidLikeFunctionCall setuid
where
  setuidBeforeSetgid(setuid, fc) and



  not isAccessed(fc) and
  func = fc.getEnclosingFunction()
select fc,
  "This function is called within " + func + ", and potentially after " +
    "$@, and may not succeed. Be sure to check the return code and errno, otherwise permissions " +
    "may not be dropped.", setuid, setuid.getTarget().getName()

import cpp
import semmle.code.cpp.ir.dataflow.DataFlow
import semmle.code.cpp.valuenumbering.GlobalValueNumbering

private class PamAuthCall extends FunctionCall {
  PamAuthCall() {
    exists(Function f | f.hasName("pam_authenticate") | f.getACallToThisFunction() = this)
  }
}

private class PamActMgmtCall extends FunctionCall {
  PamActMgmtCall() {
    exists(Function f | f.hasName("pam_acct_mgmt") | f.getACallToThisFunction() = this)
  }
}

from PamAuthCall pa, Expr handle
where
  pa.getArgument(0) = handle and
  not exists(PamActMgmtCall pac |
    globalValueNumber(handle) = globalValueNumber(pac.getArgument(0)) or
    DataFlow::localExprFlow(handle, pac.getArgument(0))
  )
select pa, "This PAM authentication call may be lead to an authorization bypass."

import cpp
import semmle.code.cpp.ir.dataflow.TaintTracking
import semmle.code.cpp.controlflow.IRGuards
import semmle.code.cpp.security.FlowSources
import OverflowDestination::PathGraph


predicate sourceSized(FunctionCall fc, Expr src) {
  fc.getTarget().hasGlobalOrStdName(["strncpy", "strncat", "memcpy", "memmove"]) and
  exists(Expr dest, Expr size, Variable v |
    fc.getArgument(0) = dest and
    fc.getArgument(1).getFullyConverted() = src and
    fc.getArgument(2) = size and
    src = v.getAnAccess().getFullyConverted() and
    size.getAChild+() = v.getAnAccess() and

    not exists(Variable other |
      dest = other.getAnAccess() and size.getAChild+() = other.getAnAccess()
    ) and

    not exists(ArrayType srctype, ArrayType desttype |
      dest.getType().getUnderlyingType() = desttype and
      src.getType().getUnderlyingType() = srctype and
      desttype.getBaseType().getUnderlyingType() = srctype.getBaseType().getUnderlyingType() and
      desttype.getArraySize() = srctype.getArraySize()
    )
  )
}

predicate readsVariable(LoadInstruction load, Variable var) {
  load.getSourceAddress().(VariableAddressInstruction).getAstVariable() = var
}

predicate hasUpperBoundsCheck(Variable var) {
  exists(RelationalOperation oper, VariableAccess access |
    oper.getAnOperand() = access and
    access.getTarget() = var and

    not oper.getAnOperand().getValue() = "0"
  )
}

predicate nodeIsBarrierEqualityCandidate(DataFlow::Node node, Operand access, Variable checkedVar) {
  readsVariable(node.asInstruction(), checkedVar) and
  any(IRGuardCondition guard).ensuresEq(access, _, _, node.asInstruction().getBlock(), true)
}

module OverflowDestinationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) { source instanceof FlowSource }

  predicate isSink(DataFlow::Node sink) { sourceSized(_, sink.asIndirectConvertedExpr()) }

  predicate isBarrier(DataFlow::Node node) {
    exists(Variable checkedVar |
      readsVariable(node.asInstruction(), checkedVar) and
      hasUpperBoundsCheck(checkedVar)
    )
    or
    exists(Variable checkedVar, Operand access |
      readsVariable(access.getDef(), checkedVar) and
      nodeIsBarrierEqualityCandidate(node, access, checkedVar)
    )
  }

  predicate observeDiffInformedIncrementalMode() { any() }

  Location getASelectedSourceLocation(DataFlow::Node source) { none() }

  Location getASelectedSinkLocation(DataFlow::Node sink) {
    exists(FunctionCall fc | result = fc.getLocation() |
      sourceSized(fc, sink.asIndirectConvertedExpr())
    )
  }
}

module OverflowDestination = TaintTracking::Global<OverflowDestinationConfig>;

from FunctionCall fc, OverflowDestination::PathNode source, OverflowDestination::PathNode sink
where
  OverflowDestination::flowPath(source, sink) and
  sourceSized(fc, sink.getNode().asIndirectConvertedExpr())
select fc, source, sink,
  "To avoid overflow, this operation should be bounded by destination-buffer size, not source-buffer size."

import cpp
import semmle.code.cpp.commons.Scanf
import semmle.code.cpp.controlflow.Guards
import semmle.code.cpp.dataflow.new.DataFlow::DataFlow
import semmle.code.cpp.ir.IR
import semmle.code.cpp.valuenumbering.GlobalValueNumbering
import ScanfChecks
import ScanfToUseFlow::PathGraph


predicate isUninitialized(Node n) {
  exists(n.asUninitialized()) or
  n.asIndirectExpr(1) instanceof AllocationExpr
}

predicate isSink(ScanfFunctionCall call, int index, Node n, Expr input) {
  input = call.getOutputArgument(index) and
  n.asIndirectExpr() = input
}


module UninitializedToScanfConfig implements ConfigSig {
  predicate isSource(Node source) { isUninitialized(source) }

  predicate isSink(Node sink) { isSink(_, _, sink, _) }

  FlowFeature getAFeature() { result instanceof FeatureEqualSourceSinkCallContext }

  int accessPathLimit() { result = 0 }
}

module UninitializedToScanfFlow = Global<UninitializedToScanfConfig>;


predicate isRelevantScanfCall(ScanfFunctionCall call, int index, Expr output) {
  exists(Node n | UninitializedToScanfFlow::flowTo(n) and isSink(call, index, n, output)) and

  not incorrectlyCheckedScanf(call)
}


predicate isSource(ScanfFunctionCall call, int index, Node n, Expr output) {
  isRelevantScanfCall(call, index, output) and
  output = call.getOutputArgument(index) and
  n.asDefiningArgument() = output
}


predicate isSink(Node n, Expr e) {
  n.asExpr() = e and
  not any(DeallocationExpr dealloc).getFreedExpr() = e
}


module ScanfToUseConfig implements ConfigSig {
  predicate isSource(Node source) { isSource(_, _, source, _) }

  predicate isSink(Node sink) { isSink(sink, _) }

  predicate isBarrierOut(Node n) {

    isSink(n, _)
    or


    exists(n.asIndirectArgument())
  }
}

module ScanfToUseFlow = Global<ScanfToUseConfig>;


predicate flowPath(
  ScanfToUseFlow::PathNode source, ScanfFunctionCall call, int index, ScanfToUseFlow::PathNode sink,
  Expr e
) {
  isSource(call, index, source.getNode(), _) and
  ScanfToUseFlow::flowPath(source, sink) and
  isSink(sink.getNode(), e)
}


int getMinimumGuardConstant(ScanfFunctionCall call, int index) {
  isSource(call, index, _, _) and
  result =
    index + 1 -
      count(ScanfFormatLiteral f, int n |


        n <= index and f.getUse() = call and f.getConversionChar(n) = "n"
      )
}


predicate hasNonGuardedAccess(
  ScanfToUseFlow::PathNode source, ScanfFunctionCall call, ScanfToUseFlow::PathNode sink, Expr e,
  int minGuard
) {
  exists(int index |
    flowPath(source, call, index, sink, e) and
    minGuard = getMinimumGuardConstant(call, index)
  |
    not exists(GuardCondition guard |

      guard
          .ensuresEq(globalValueNumber(call).getAnExpr(), any(int k | minGuard <= k),
            e.getBasicBlock(), true)
      or

      guard
          .ensuresLt(globalValueNumber(call).getAnExpr(), any(int k | minGuard <= k),
            e.getBasicBlock(), false)
    )
  )
}

from
  ScanfToUseFlow::PathNode source, ScanfToUseFlow::PathNode sink, ScanfFunctionCall call, Expr e,
  int minGuard
where hasNonGuardedAccess(source, call, sink, e, minGuard)
select e, source, sink,
  "This variable is read, but may not have been written. " +
    "It should be guarded by a check that the $@ returns at least " + minGuard + ".", call,
  call.toString()

import cpp
import semmle.code.cpp.dataflow.new.DataFlow
import semmle.code.cpp.security.flowafterfree.FlowAfterFree
import DoubleFree::PathGraph


predicate isFree(DataFlow::Node n, Expr e) { isFree(_, n, e, _) }

module DoubleFreeParam implements FlowFromFreeParamSig {
  predicate isSink = isFree/2;

  predicate isExcluded = isExcludedMmFreePageFromMdl/2;

  predicate sourceSinkIsRelated = defaultSourceSinkIsRelated/2;
}

module DoubleFree = FlowFromFree<DoubleFreeParam>;

from DoubleFree::PathNode source, DoubleFree::PathNode sink, DeallocationExpr dealloc, Expr e2
where
  DoubleFree::flowPath(source, sink) and
  isFree(source.getNode(), _, _, dealloc) and
  isFree(sink.getNode(), e2)
select sink.getNode(), source, sink, "Memory pointed to by $@ may already have been freed by $@.",
  e2, e2.toString(), dealloc, dealloc.toString()

import cpp
import semmle.code.cpp.commons.Buffer
import semmle.code.cpp.ir.dataflow.DataFlow
import semmle.code.cpp.rangeanalysis.SimpleRangeAnalysis
import semmle.code.cpp.ConfigurationTestFile
import LoopBounds

private predicate staticBufferBase(VariableAccess access, Variable v) {
  v.getType().(ArrayType).getBaseType() instanceof CharType and
  access = v.getAnAccess() and
  not memberMayBeVarSize(_, v) and
  not access.isUnevaluated()
}

predicate staticBuffer(VariableAccess access, Variable v, int size) {
  staticBufferBase(access, v) and
  size = getBufferSize(access, _)
}

class BufferAccess extends ArrayExpr {
  BufferAccess() {
    exists(int size |
      staticBuffer(this.getArrayBase(), _, size) and
      size != 0
    ) and


    not exists(Macro m |
      m.getName() = "strcmp" and
      m.getAnInvocation().getAnExpandedElement() = this
    ) and

    reachable(this)
  }

  int bufferSize() { staticBuffer(this.getArrayBase(), _, result) }

  Variable buffer() { result.getAnAccess() = this.getArrayBase() }
}

predicate overflowOffsetInLoop(BufferAccess bufaccess, string msg) {
  exists(ClassicForLoop loop |
    loop.getStmt().getAChild*() = bufaccess.getEnclosingStmt() and
    loop.limit() >= bufaccess.bufferSize() and
    loop.counter().getAnAccess() = bufaccess.getArrayOffset() and

    not upperBound(bufaccess.getArrayOffset().getFullyConverted()) < bufaccess.bufferSize() and

    not upperBoundMayBeWidened(bufaccess.getArrayOffset().getFullyConverted()) and
    msg =
      "Potential buffer-overflow: counter '" + loop.counter().toString() + "' <= " +
        loop.limit().toString() + " but '" + bufaccess.buffer().getName() + "' has " +
        bufaccess.bufferSize().toString() + " elements."
  )
}

predicate bufferAndSizeFunction(Function f, int buf, int size) {
  f.hasGlobalName("read") and buf = 1 and size = 2
  or
  f.hasGlobalOrStdName("fgets") and buf = 0 and size = 1
  or
  f.hasGlobalOrStdName("strncpy") and buf = 0 and size = 2
  or
  f.hasGlobalOrStdName("strncat") and buf = 0 and size = 2
  or
  f.hasGlobalOrStdName("memcpy") and buf = 0 and size = 2
  or
  f.hasGlobalOrStdName("memmove") and buf = 0 and size = 2
  or
  f.hasGlobalOrStdName("snprintf") and buf = 0 and size = 1
  or
  f.hasGlobalOrStdName("vsnprintf") and buf = 0 and size = 1
}

class CallWithBufferSize extends FunctionCall {
  CallWithBufferSize() { bufferAndSizeFunction(this.getTarget(), _, _) }

  Expr buffer() {
    exists(int i |
      bufferAndSizeFunction(this.getTarget(), i, _) and
      result = this.getArgument(i)
    )
  }

  Expr statedSizeExpr() {
    exists(int i |
      bufferAndSizeFunction(this.getTarget(), _, i) and
      result = this.getArgument(i)
    )
  }

  int statedSizeValue() {


    result =
      upperBound(this.statedSizeExpr())
          .minimum(min(Expr statedSizeSrc |
              DataFlow::localExprFlow(statedSizeSrc, this.statedSizeExpr())
            |
              statedSizeSrc.getValue().toInt()
            ))
  }
}

predicate wrongBufferSize(Expr error, string msg) {
  exists(CallWithBufferSize call, int bufsize, Variable buf, int statedSize |
    staticBuffer(call.buffer(), buf, bufsize) and
    statedSize = call.statedSizeValue() and
    statedSize > bufsize and
    error = call.statedSizeExpr() and
    msg =
      "Potential buffer-overflow: '" + buf.getName() + "' has size " + bufsize.toString() + " not " +
        statedSize + "."
  )
}

predicate outOfBounds(BufferAccess bufaccess, string msg) {
  exists(int size, int access, string buf |
    buf = bufaccess.buffer().getName() and
    bufaccess.bufferSize() = size and
    bufaccess.getArrayOffset().getValue().toInt() = access and
    (
      access > size
      or
      access = size and
      not exists(AddressOfExpr addof | bufaccess = addof.getOperand()) and
      not exists(BuiltInOperationBuiltInOffsetOf offsetof | offsetof.getAChild() = bufaccess)
    ) and
    msg =
      "Potential buffer-overflow: '" + buf + "' has size " + size.toString() + " but '" + buf + "[" +
        access.toString() + "]' may be accessed here."
  )
}

from Element error, string msg
where
  (
    overflowOffsetInLoop(error, msg) or
    wrongBufferSize(error, msg) or
    outOfBounds(error, msg)
  ) and
  not error.getFile() instanceof ConfigurationTestFile 
select error, msg

import MemoryFreed
import semmle.code.cpp.controlflow.StackVariableReachability


predicate mayCallFunction(Expr call, Function f) {
  call.(FunctionCall).getTarget() = f or
  call.(VariableCall).getVariable().getAnAssignedValue().getAChild*().(FunctionAccess).getTarget() =
    f
}

predicate allocCallOrIndirect(Expr e) {

  e.(AllocationExpr).requiresDealloc() and



  allocMayBeFreed(e)
  or
  exists(ReturnStmt rtn |

    mayCallFunction(e, rtn.getEnclosingFunction()) and
    (

      allocCallOrIndirect(rtn.getExpr())
      or

      exists(StackVariable v |
        v = rtn.getExpr().(VariableAccess).getTarget() and
        allocCallOrIndirect(v.getAnAssignedValue()) and
        not assignedToFieldOrGlobal(v, _)
      )
    )
  )
}


predicate verifiedRealloc(FunctionCall reallocCall, Variable v, ControlFlowNode verified) {
  reallocCall.(AllocationExpr).getReallocPtr() = v.getAnAccess() and
  (
    exists(Variable newV, ControlFlowNode node |


      newV.getAnAssignedValue() = reallocCall and
      node.(AnalysedExpr).getNonNullSuccessor(newV) = verified and





      newV != v
    )
    or


    reallocCall.(AllocationExpr).getReallocPtr().getValue() = "0" and
    verified = reallocCall
  )
}

predicate freeCallOrIndirect(ControlFlowNode n, Variable v) {

  n.(DeallocationExpr).getFreedExpr() = v.getAnAccess() and
  not exists(n.(AllocationExpr).getReallocPtr())
  or

  verifiedRealloc(_, v, n)
  or
  exists(FunctionCall midcall, Function mid, int arg |

    n.(Call).getArgument(arg) = v.getAnAccess() and
    mayCallFunction(n, mid) and
    midcall.getEnclosingFunction() = mid and
    freeCallOrIndirect(midcall, mid.getParameter(arg))
  )
}

predicate allocationDefinition(StackVariable v, ControlFlowNode def) {
  exists(Expr expr | exprDefinition(v, def, expr) and allocCallOrIndirect(expr))
}

class AllocVariableReachability extends StackVariableReachabilityWithReassignment {
  AllocVariableReachability() { this = "AllocVariableReachability" }

  override predicate isSourceActual(ControlFlowNode node, StackVariable v) {
    allocationDefinition(v, node)
  }

  override predicate isSinkActual(ControlFlowNode node, StackVariable v) {

    exists(node.(AnalysedExpr).getNullSuccessor(v)) or
    freeCallOrIndirect(node, v) or
    assignedToFieldOrGlobal(v, node) or

    v.getFunction() = node.(ReturnStmt).getEnclosingFunction()
  }

  override predicate isBarrier(ControlFlowNode node, StackVariable v) { definitionBarrier(v, node) }
}


predicate allocatedVariableReaches(StackVariable v, ControlFlowNode def, ControlFlowNode node) {
  exists(AllocVariableReachability r |

    r.reachesTo(def, _, node, v)
    or

    r.isSource(def, v) and
    node = def
  )
}

class AllocReachability extends StackVariableReachabilityExt {
  AllocReachability() { this = "AllocReachability" }

  override predicate isSource(ControlFlowNode node, StackVariable v) {
    allocationDefinition(v, node)
  }

  override predicate isSink(ControlFlowNode node, StackVariable v) {
    v.getFunction() = node.(ReturnStmt).getEnclosingFunction()
  }

  override predicate isBarrier(
    ControlFlowNode source, ControlFlowNode node, ControlFlowNode next, StackVariable v
  ) {
    this.isSource(source, v) and
    next = node.getASuccessor() and


    exists(StackVariable v0 | allocatedVariableReaches(v0, source, node) |
      node.(AnalysedExpr).getNullSuccessor(v0) = next or
      freeCallOrIndirect(node, v0) or
      assignedToFieldOrGlobal(v0, node)
    )
  }
}


predicate allocationReaches(ControlFlowNode def, ControlFlowNode node) {
  exists(AllocReachability r | r.reaches(def, _, node))
}

predicate assignedToFieldOrGlobal(StackVariable v, Expr e) {


  e.(Assignment).getRValue() = v.getAnAccess() and
  not e.(Assignment).getLValue().(VariableAccess).getTarget() instanceof StackVariable
  or
  exists(Expr midExpr, Function mid, int arg |

    e.(FunctionCall).getArgument(arg) = v.getAnAccess() and
    mayCallFunction(e, mid) and
    midExpr.getEnclosingFunction() = mid and
    assignedToFieldOrGlobal(mid.getParameter(arg), midExpr)
  )
  or

  e.(ConstructorFieldInit).getExpr() = v.getAnAccess()
}

from ControlFlowNode def, ReturnStmt ret
where
  allocationReaches(def, ret) and
  not exists(StackVariable v |
    allocatedVariableReaches(v, def, ret) and
    ret.getAChild*() = v.getAnAccess()
  )
select def, "This memory allocation may not be released at $@.", ret, "this exit point"

import cpp


predicate defines(ControlFlowNode s, Variable lv) {
  exists(VariableAccess va | va = s and va.getTarget() = lv and va.isUsedAsLValue())
}


predicate uses(ControlFlowNode s, Variable lv) {
  exists(VariableAccess va |
    va = s and
    va.getTarget() = lv and
    va.isRValue() and
    not va.getParent+() instanceof SizeofOperator
  )
}


predicate noDefPath(LocalVariable lv, ControlFlowNode n) {
  n.(DeclStmt).getADeclaration() = lv and not exists(lv.getInitializer())
  or
  exists(ControlFlowNode p | noDefPath(lv, p) and n = p.getASuccessor() and not defines(p, lv))
}

predicate isAggregateType(Type t) { t instanceof Class or t instanceof ArrayType }


predicate undefinedLocalUse(VariableAccess va) {
  exists(LocalVariable lv |


    not isAggregateType(lv.getUnderlyingType()) and
    not lv.isStatic() and 
    not lv.getType().hasName("va_list") and
    va = lv.getAnAccess() and
    noDefPath(lv, va) and
    uses(va, lv)
  )
}


predicate uninitialisedGlobal(GlobalVariable gv) {
  exists(VariableAccess va |
    not isAggregateType(gv.getUnderlyingType()) and
    va = gv.getAnAccess() and
    va.isRValue() and
    not gv.hasInitializer() and
    not gv.hasSpecifier("extern") and
    not gv.isStatic() 
  )
}

from Element elt
where undefinedLocalUse(elt) or uninitialisedGlobal(elt)
select elt, "Variable '" + elt.toString() + "' is not initialized."

import cpp
import semmle.code.cpp.pointsto.CallGraph

predicate initFunc(GlobalVariable v, Function f) {
  exists(VariableAccess access |
    v.getAnAccess() = access and
    access.isUsedAsLValue() and
    access.getEnclosingFunction() = f
  )
}


predicate dominatingInitInFunc(GlobalVariable v, Function f, ControlFlowNode node) {
  exists(VariableAccess initAccess |
    v.getAnAccess() = initAccess and
    initAccess.isUsedAsLValue() and
    initAccess.getEnclosingFunction() = f and
    dominates(initAccess, node)
  )
}

predicate safeAccess(VariableAccess access) {

  exists(SizeofExprOperator e | e.getAChild*() = access)
}

predicate useFunc(GlobalVariable v, Function f) {
  exists(VariableAccess access |
    v.getAnAccess() = access and
    access.isRValue() and
    access.getEnclosingFunction() = f and
    not safeAccess(access) and
    not dominatingInitInFunc(v, f, access)
  )
}

predicate uninitialisedBefore(GlobalVariable v, Function f) {
  f.hasGlobalName("main") and
  not initialisedAtDeclaration(v) and
  not isStdlibVariable(v)
  or
  exists(Call call, Function g |
    uninitialisedBefore(v, g) and
    call.getEnclosingFunction() = g and
    (not functionInitialises(g, v) or locallyUninitialisedAt(v, call)) and
    resolvedCall(call, f)
  )
}

predicate functionInitialises(Function f, GlobalVariable v) {
  initFunc(v, f)
  or
  exists(Call call |
    call.getEnclosingFunction() = f and
    initialisedBy(v, call)
  )
}



predicate locallyUninitialisedAt(GlobalVariable v, Call call) {
  functionInitialises(call.getEnclosingFunction(), v) and
  (
    firstCall(call)
    or
    exists(Call mid |
      locallyUninitialisedAt(v, mid) and not initialisedBy(v, mid) and callPair(mid, call)
    )
  ) and
  not dominatingInitInFunc(v, call.getEnclosingFunction(), call)
}

predicate initialisedBy(GlobalVariable v, Call call) {
  exists(Function f |
    resolvedCall(call, f) and
    initialises(v, f)
  )
}

predicate initialises(GlobalVariable v, Function f) {
  initFunc(v, f)
  or
  exists(Function mid | initialises(v, mid) and allCalls(f, mid))
}

predicate firstCall(Call call) { beforeCall(call) }

predicate beforeCall(ControlFlowNode node) {
  exists(Function f | f.getBlock() = node)
  or
  exists(ControlFlowNode mid |
    beforeCall(mid) and
    not mid instanceof Call and
    node = mid.getASuccessor()
  )
}

predicate callPair(Call call, Call successor) { callReaches(call, successor) }

predicate callReaches(Call call, ControlFlowNode successor) {
  call.getASuccessor() = successor
  or
  exists(ControlFlowNode mid |
    callReaches(call, mid) and
    not mid instanceof Call and
    mid.getASuccessor() = successor
  )
}


predicate initialisedAtDeclaration(GlobalVariable v) { exists(v.getInitializer()) }


predicate isStdlibVariable(GlobalVariable v) { v.hasGlobalName(["stdin", "stdout", "stderr"]) }

from GlobalVariable v, Function f
where
  uninitialisedBefore(v, f) and
  useFunc(v, f)
select f, "The variable $@ is used in this function but may not be initialized when it is called.",
  v, v.getName()

